import{_ as a,o as s,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"fr/car-wash/index.md","filePath":"fr/car-wash/index.md"}'),n={name:"fr/car-wash/index.md"};function o(i,e,l,u,c,d){return s(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>On s&#39;arrête, on choisit une formule, et le véhicule traverse les brosses, la mousse, les arches de rinçage et le séchoir à vapeur, pendant que tout le monde autour voit le même lavage. À pied, les joueurs prennent un nettoyeur haute pression et enlèvent la saleté niveau par niveau. Chaque emplacement se place en jeu et chaque réglage se modifie en jeu.</p><h2 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h2><ul><li><strong>Tunnels de lavage</strong> : brosses à la largeur du véhicule, arches de savon et de rinçage, séchoir à vapeur, synchronisés pour tous les joueurs proches. Voir <a href="/fr/car-wash/tunnels">Tunnels</a>.</li><li><strong>Formules de lavage</strong> : nom, prix, vitesse et étapes (savon, rinçage, séchage, cire). La cire garde le véhicule propre le temps que vous choisissez.</li><li><strong>Nettoyeurs haute pression</strong> sur n&#39;importe quel prop du monde que vous listez, ou sur des stations que vous placez, payés par niveau de saleté. Voir <a href="/fr/car-wash/pressure-washers">Nettoyeurs haute pression</a>.</li><li><strong>Éditeur de tunnels en jeu</strong> : créez un tunnel là où vous êtes ou copiez une station du jeu de base, déplacez chaque élément au clavier, enregistrez.</li><li><strong>Tout dans <code>/nay</code></strong> : prix, formules, remises par métier, compte de paiement, classes de véhicules refusées, blips avec un choix visuel d&#39;icône et de couleur. Voir <a href="/fr/car-wash/settings">Réglages</a>.</li><li><strong>Juste et sûr</strong> : un véhicule par tunnel, contrôles de sens et de voie bloquée, paiements et réservation du tunnel validés par le serveur.</li><li><strong>Remises par métier</strong> et pourcentage de prix par tunnel. Les joueurs paient en liquide, par la banque, ou en liquide puis par la banque.</li><li><strong>Respect de la carte</strong> : les brosses fixes de la carte sont masquées le long de chaque tunnel et reviennent à l&#39;arrêt de la ressource. À Strawberry, les fichiers de carte sans brosses remplacent la station d&#39;origine.</li><li><strong>API HTTP et webhooks</strong> : historique des lavages et statistiques pour votre site ou votre bot, un message Discord à chaque lavage. Voir <a href="/fr/car-wash/api">API et webhooks</a>.</li><li><strong>Six langues</strong> : anglais, français, espagnol, portugais, polonais, allemand.</li></ul><h2 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h2><ul><li>Frameworks : ESX Legacy, QBCore, QBox, ox_core, détectés automatiquement.</li><li>Target (facultatif, pour les nettoyeurs) : ox_target ou qb-target. Sans target, les joueurs utilisent une invite de touche.</li><li>Dépendances : oxmysql et <code>nay_lib</code> (fourni avec votre achat).</li></ul><h2 id="performances" tabindex="-1">Performances <a class="header-anchor" href="#performances" aria-label="Permalink to &quot;Performances&quot;">​</a></h2><table tabindex="0"><thead><tr><th>État</th><th>Client (resmon)</th></tr></thead><tbody><tr><td>Au repos</td><td>0,00 ms</td></tr><tr><td>Pendant un lavage</td><td>environ 0,08 ms</td></tr></tbody></table><p>Mesuré avec resmon sur le build 3751 du jeu.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Toutes les étapes sont sur la page <a href="/fr/getting-started">Prise en main</a>. Donnez-vous ensuite <code>nay_car_wash.config</code> (ou <code>nay.admin</code>) et ouvrez <code>/nay</code>. Deux tunnels sont prêts dès l&#39;installation : Strawberry et Little Seoul.</p>`,12)])])}const g=a(n,[["render",o]]);export{h as __pageData,g as default};
